 static final String NAME="天天看球",BASE="https://www.ttkq0dajy010.xyz",CONFIG="https://tt-cfg-01.aptt8bnhq403.xyz/1ftmbzp6s06i8uag9tavp.s";
 static JSONObject cachedConfig;static long configAt;
 static synchronized JSONObject config()throws Exception{if(cachedConfig==null||System.currentTimeMillis()-configAt>600000){JSONObject value=decodeConfig(HttpData.get(CONFIG,BASE+"/",false).body);String host=value.optString("host");if(!HttpData.publicUrl(host)||!host.startsWith("https://"))throw new IOException("来源配置无效");cachedConfig=value;configAt=System.currentTimeMillis();}return cachedConfig;}
 public static JSONObject decodeConfig(String hex)throws Exception{hex=hex.trim();if(hex.length()>524288||!hex.matches("[0-9a-fA-F]+")||hex.length()%32!=0)throw new IOException("来源配置格式无效");byte[] data=new byte[hex.length()/2];for(int i=0;i<data.length;i++)data[i]=(byte)Integer.parseInt(hex.substring(i*2,i*2+2),16);byte[] key={80,(byte)150,34,102,112,121,96,102,49,112,104,(byte)128,51,24,40,102};Cipher cipher=Cipher.getInstance("AES/ECB/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"));String text=new String(cipher.doFinal(data),"UTF-8");int end=text.lastIndexOf('}');if(end<0)throw new IOException("来源配置内容无效");return new JSONObject(text.substring(0,end+1));}
 static String base64(byte[] data){String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";StringBuilder out=new StringBuilder();for(int i=0;i<data.length;i+=3){int a=data[i]&255,b=i+1<data.length?data[i+1]&255:0,c=i+2<data.length?data[i+2]&255:0;out.append(alphabet.charAt(a>>2)).append(alphabet.charAt(((a&3)<<4)|(b>>4))).append(i+1<data.length?alphabet.charAt(((b&15)<<2)|(c>>6)):'=').append(i+2<data.length?alphabet.charAt(c&63):'=');}return out.toString();}
 public static String verify(String path,long seconds)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec("uinapveppygeotoyqmtrcdhuzdfukvsx".getBytes("UTF-8"),"HmacSHA256"));return seconds+"-"+URLEncoder.encode(base64(mac.doFinal((path+seconds).getBytes("UTF-8"))),"UTF-8");}
 public static String anonymousHash(long seconds)throws Exception{String prefix="tt,3,1000000,tt-pc,,"+seconds;byte[] hash=MessageDigest.getInstance("SHA-256").digest((prefix+"526dc69734aaacba8481c479f3cb2cd7").getBytes("UTF-8"));StringBuilder out=new StringBuilder(prefix+",");for(byte b:hash)out.append(String.format(Locale.US,"%02x",b&255));return out.toString();}
 static JSONArray rooms()throws Exception{long seconds=System.currentTimeMillis()/1000;String path="/api?method=listUsersLive&random="+Math.random();Map<String,String> headers=new LinkedHashMap<String,String>();headers.put("aghash",anonymousHash(seconds));JSONObject root=(JSONObject)HttpData.json(HttpData.postForm(config().getString("host")+path+"&verify="+verify(path,seconds),BASE+"/","",headers).body);if(!root.optBoolean("success"))throw new IOException("来源接口暂不可用");return root.getJSONArray("data");}
 static JSONObject child(JSONObject value,String name){JSONObject c=value==null?null:value.optJSONObject(name);return c==null?new JSONObject():c;}
 public static boolean allowed(JSONObject room){String title=room.optString("title"),cls=child(child(room,"joinMap"),"cls").optString("name");return !room.optString("uid").isEmpty()&&(cls.equals("足球")||cls.equals("篮球")||cls.equals("网球")||cls.equals("台球")||cls.equals("电竞"))&&room.optInt("islive")==1&&room.optInt("hide")==0&&room.optInt("isvideo")==0&&room.optInt("type")==0&&room.optString("typeVal").isEmpty()&&!title.isEmpty()&&!SourceSafety.promotional(title+" "+child(child(room,"joinMap"),"room").optString("name"))&&!title.matches(".*(回放|重播|录播).* ".trim())&&StreamResolver.direct(room.optString("pull"));}
 public static List<Feeds.Match> parse(JSONArray rooms,String fileBase)throws Exception{LinkedHashMap<String,Feeds.Match> out=new LinkedHashMap<String,Feeds.Match>();for(int i=0;i<rooms.length();i++){JSONObject r=rooms.getJSONObject(i);if(!allowed(r))continue;JSONObject joins=child(r,"joinMap"),event=child(joins,"schedule");String title=r.optString("title"),home=event.optString("teamNamea"),away=event.optString("teamNameb"),time=event.optString("beginTime"),sportName=child(joins,"cls").optString("name"),sport=sportName.equals("足球")?"1":sportName.equals("篮球")?"2":sportName.equals("网球")?"3":sportName.equals("台球")?"snooker":"esports";boolean linked=!home.isEmpty()&&!away.isEmpty()&&Events.canonical(title).contains(Events.canonical(home))&&Events.canonical(title).contains(Events.canonical(away))&&Events.epoch(time)>0;String id=linked?sport+":"+event.optString("id"):"room:"+r.optString("uid");Feeds.Match m=out.get(id);if(m==null){m=MoreSources.match(NAME,id);m.title=title;m.sport=sport;m.status="live";m.room=r.optString("uid");m.estimated=!linked;m.league=child(joins,"match").optString("nameAbbr");String thumb=r.optString("thumb");if(!thumb.isEmpty()&&!fileBase.isEmpty())m.cover=Feeds.absolute(fileBase+"file/",thumb);if(linked){m.home=home;m.away=away;m.time=time;m.eventState=event.optInt("status",-1)==1?"live":event.optInt("status",-1)==0?"upcoming":event.optInt("status",-1)==2?"finished":"";m.score=event.optString("scorea")+" : "+event.optString("scoreb");}m.raw.put("rooms",new JSONArray());out.put(id,m);}String name=child(joins,"room").optString("name","主播");m.raw.getJSONArray("rooms").put(new JSONObject().put("uid",r.optString("uid")).put("id",r.optString("id")).put("title",title).put("name",name));}for(Feeds.Match m:out.values())MoreSources.pack(m);return new ArrayList<Feeds.Match>(out.values());}
 static Feeds.Page fetch(String view,int number)throws Exception{return MoreSources.page(parse(rooms(),config().optString("download")),number);}
 static ArrayList<Feeds.Line> lines(Feeds.Match match)throws Exception{JSONArray refs=match.raw.getJSONObject("extra").getJSONArray("rooms");ArrayList<Feeds.Line> out=new ArrayList<Feeds.Line>();for(int i=0;i<refs.length();i++){JSONObject r=refs.getJSONObject(i);Feeds.Line l=new Feeds.Line(r.optString("name")+" · HLS",r.getString("uid"),"");l.referer=BASE+"/";out.add(l);}return out;}
 static String resolve(Feeds.Match match,Feeds.Line line)throws Exception{JSONArray refs=match.raw.getJSONObject("extra").getJSONArray("rooms");JSONObject ref=null;for(int i=0;i<refs.length();i++)if(refs.getJSONObject(i).optString("uid").equals(line.id))ref=refs.getJSONObject(i);if(ref==null)throw new IOException("缺少当前房间");JSONArray rooms=rooms();for(int i=0;i<rooms.length();i++){JSONObject r=rooms.getJSONObject(i);if(r.optString("uid").equals(line.id)&&r.optString("id").equals(ref.optString("id"))){if(!allowed(r)||!r.optString("title").equals(ref.getString("title")))throw new IOException("直播间已离线或更换赛事，请刷新");return r.getString("pull");}}throw new IOException("主播已离线，请更换线路");}
